operation.add:
if ($this->config->get('esputnik_site_script')) {
	$esputnik_site_script = $this->config->get('esputnik_site_script');
	if (!empty($esputnik_site_script)) {
		$data['esputnik_site_script'] = html_entity_decode($esputnik_site_script);
	}
	$esputnik_web_push_script = $this->config->get('esputnik_web_push_script');
	if (!empty($esputnik_web_push_script)) {
		$data['esputnik_web_push_script'] = html_entity_decode($esputnik_web_push_script);
	}
	$route = !empty($this->request->get['route']) ? $this->request->get['route'] : '';
	$begin_checkout_routes = [
		'checkout/cart',
		'checkout/checkout',
		'checkout/simplecheckout',
		'checkout/unicheckout',
		'checkout/uni_checkout',
		'checkout/revcheckout',
		'revolution/revcheckout',
		'checkout/oct_fastorder',
		'checkout/fastorder',
		'checkout/onepcheckout',
		'checkout/checkout_two_step',
		'extension/module/buy',
		'checkout/buy',
		'extension/quickcheckout/checkout',
		'lightcheckout/checkout',
		'extension/module/custom',
		'tmdqc/tmdcheckout',
		'quickcheckout/checkout',
	];
	if (in_array($route, $begin_checkout_routes)) {
		$data['esputnik_event'] = "<script>document.addEventListener('DOMContentLoaded', function() {if (typeof eS === 'function') { eS('sendEvent', 'StatusCartPage'); }})</script>";
	}
	if (in_array($route, ['common/home', ''])) {
		$data['esputnik_event'] = "<script>document.addEventListener('DOMContentLoaded', function() {if (typeof eS === 'function') { eS('sendEvent', 'MainPage'); }})</script>";
	}
	if (in_array($route, ['error/not_found'])) {
		$data['esputnik_event'] = "<script>document.addEventListener('DOMContentLoaded', function() {if (typeof eS === 'function') { eS('sendEvent', 'NotFound'); }})</script>";
	}
	if (isset($this->session->data['customer_id']) && empty($this->session->data['esputnik_customer_data'])) {
		$this->load->model('extension/module/esputnik');
		$this->model_extension_module_esputnik->sendCustomerData();
		$this->session->data['esputnik_customer_data'] = true;
	}
}

{% if esputnik_site_script %}{{ esputnik_site_script }}{% endif %}
{% if esputnik_web_push_script %}{{ esputnik_web_push_script }}{% endif %}
{% if esputnik_event %}{{ esputnik_event }}{% endif %}

{% if esputnik_event %}
<script>
if (typeof eS !== 'undefined') {
	product_page_event = {{ esputnik_event }};
	eS('sendEvent', 'ProductPage', product_page_event);
}			
</script>
{% endif %}

{% if esputnik_event %}
<script>
if (typeof eS !== 'undefined') {
	search_page_event = {{ esputnik_event }};
	eS('sendEvent', 'SearchRequest', search_page_event);
}			
</script>
{% endif %}

{% if esputnik_event %}
<script>
if (typeof eS !== 'undefined') {
	category_page_event = {{ esputnik_event }};
	eS('sendEvent', 'CategoryPage', category_page_event);
}			
</script>
{% endif %}
